// ═══════════════════════════════════════════════════════════
// DEFINE CATEGORIES — Outlook colour presets for each priority
//
// Outlook preset colours:
//   preset0 = Red, preset1 = Orange, preset2 = Brown,
//   preset3 = Yellow, preset4 = Green, preset5 = Teal,
//   preset6 = Olive, preset7 = Blue, preset8 = Purple,
//   preset9 = Cranberry
// ═══════════════════════════════════════════════════════════
return [
  { json: { displayName: 'IMMEDIATE', color: 'preset0' } },      // Red
  { json: { displayName: 'IMPORTANT', color: 'preset3' } },      // Yellow
  { json: { displayName: 'NOT_IMPORTANT', color: 'preset7' } },  // Blue
];

// ═══════════════════════════════════════════════════════════
// REPORT — summarise what was created
// ═══════════════════════════════════════════════════════════
const items = $input.all();
const results = items.map(item => ({
  category: item.json.displayName || 'unknown',
  status: item.json.error ? 'already exists or failed' : 'created',
}));

return [{ json: { message: 'Category setup complete', results } }];
